#include <iostream>
#include <vector>
using namespace std;

typedef vector<long long> row;
typedef vector<row> matrix;

long long N; int K;
matrix R[40];
matrix D[100][40];

void make_matrix(matrix& M, int r, int c) {
    M.resize(r);
    for (int i = 0; i < r; ++i) M[i].assign(c, 0);
}

matrix multiply_matrices(const matrix& A, const matrix& B) {
    matrix C(A.size(), vector<long long>(B[0].size(), 0));
    for (size_t i = 0; i < A.size(); ++i)
        for (size_t j = 0; j < B[0].size(); ++j)
            for (size_t k = 0; k < B.size(); ++k)
                C[i][j] += A[i][k] * B[k][j];
    return C;
}

int main() {
    cin >> N >> K;
    int count = 0; long long p = 1;
    while (p <= N) { p *= K; count++; }
    p /= K;
    vector<int> digits(count);
    for (int i = 0; i < count; ++i) {
        digits[i] = N / p;
        N %= p;
        p /= K;
    }
    for (int i = 0; i <= K; ++i) make_matrix(R[i], K + 1, K + 1);
    for (int i = 0; i <= count; ++i)
        for (int j = 0; j < K; ++j) make_matrix(D[i][j], K + 1, K + 1);
    R[0][K][K] = 1; R[1][K][K] = 1;
    for (int j = 0; j < K; ++j) R[0][j][j] = 1;
    for (int j = 0; j < K; ++j) R[1][(j + K - 1) % K][j] = 1;
    for (int j = 2; j <= K; ++j) R[j] = multiply_matrices(R[j - 1], R[1]);
    for (int j = 0; j <= K; ++j) {
        D[0][0][j][j] = 1;
        D[0][0][j][0] = 1;
    }
    int total_count = count;
    for (int i = 0; i <= total_count; ++i) {
        for (int j = 1; j < K; ++j) {
            D[i][j] = multiply_matrices(multiply_matrices(R[K - j], D[i][0]), R[j]);
        }
        if (i + 1 <= total_count) D[i + 1][0] = D[i][K - 1];
    }
    matrix answer(1, vector<long long>(K + 1, 0)); answer[0][K] = 1;
    int sum_modulo = 0;
    for (int i = 0; i < total_count; ++i) {
        if (digits[i] != 0)
            answer = multiply_matrices(multiply_matrices(R[K - sum_modulo], D[total_count - i - 1][digits[i] - 1]), R[sum_modulo]);
        sum_modulo += digits[i]; sum_modulo %= K;
    }
    long long total_result = 0;
    for (int i = 0; i <= K; ++i) total_result += answer[0][i];
    cout << total_result << endl;
}
